#branch-banner {
    position: fixed;
    left:50%;
    top:50%;
    translate: -50% -50%;
}

animation.css:
.branch-banner-enter {
    animation: branch-journey-fade-in 0.25s ease both;
}
@keyframes branch-journey-fade-in { from { opacity: 0; } to { opacity: 1; } }
.branch-banner-exit {
    animation: branch-journey-fade-out 0.25s ease both;
}
@keyframes branch-journey-fade-out { from { opacity: 1; } to { opacity: 0; } }
